import{_ as s}from"./chunks/icon.B7gRmRZx.js";import{_ as t,a as r,b as n,c as i,d as o,e as a,f as l,g as u,h as c,i as p,j as d}from"./chunks/0.1.12-193-neustart-de.NjH6ArMk.js";import{_ as m,o as g,c as h,a3 as b}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.23 avec moteur d’exécution en direct, Blocks JS et diagrammes fonctionnels pour Home Assistant.","frontmatter":{"title":"Logic Studio","description":"HA Logic Studio Pro 0.1.23 avec moteur d’exécution en direct, Blocks JS et diagrammes fonctionnels pour Home Assistant."},"headers":[],"relativePath":"fr/projects/logic-studio/index.md","filePath":"fr/projects/logic-studio/index.md","lastUpdated":1794424237000}'),v={name:"fr/projects/logic-studio/index.md"};function f(L,e,A,x,k,q){return g(),h("div",null,[...e[0]||(e[0]=[b('<h1 id="logic-studio" tabindex="-1"><img class="package-icon" src="'+s+`" width="40" height="40" alt=""> Logic Studio <a class="header-anchor" href="#logic-studio" aria-label="Permalink to &quot;&lt;img class=&quot;package-icon&quot; src=&quot;/images/logic-studio/icon.svg&quot; width=&quot;40&quot; height=&quot;40&quot; alt=&quot;&quot;&gt; Logic Studio&quot;">​</a></h1><p><strong>0.1.12 – mise à jour publique de test, 8 novembre 2026.</strong> Interface et documentation sont désormais disponibles en <strong>DE/EN/FR</strong>. Logic Studio est une application HA autonome pour les plans à blocs fonctionnels, indépendante de Grafik Visual Studio et Blocks for HA. Le canevas React Flow conserve ses blocs personnalisés, connexions typées, zoom et MiniMap ; bibliothèques et licences sont incluses localement.</p><div class="warning custom-block"><p class="custom-block-title">Version de test</p><p>Installer d’abord sur un système de test et créer une sauvegarde complète. Les propriétés natives détaillées sont actuellement modifiables en JSON. L’application ne réécrit pas les automatisations/scripts dans HA et ne commande aucun appareil. Vérifier et installer soi-même les sorties générées.</p></div><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/logic-studio-v0.1.12" target="_blank" rel="noreferrer">Version de test GitHub et ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/logic_studio" target="_blank" rel="noreferrer">Sources dans le dépôt commun</a></p><h2 id="ha-logic-studio-pro-0-1-23" tabindex="-1">HA Logic Studio Pro 0.1.23 <a class="header-anchor" href="#ha-logic-studio-pro-0-1-23" aria-label="Permalink to &quot;HA Logic Studio Pro 0.1.23&quot;">​</a></h2><p>HA Logic Studio Pro est une application Home Assistant distincte dans le dépôt commun UGSo. La version <strong>0.1.23</strong> est une mise à jour publique de test du moteur d’exécution en direct. Créer une sauvegarde complète et essayer d’abord la mise à jour sur un système de test.</p><h3 id="nouveautes-depuis-la-version-0-1-12" tabindex="-1">Nouveautés depuis la version 0.1.12 <a class="header-anchor" href="#nouveautes-depuis-la-version-0-1-12" aria-label="Permalink to &quot;Nouveautés depuis la version 0.1.12&quot;">​</a></h3><ul><li><strong>Arborescence et éditeurs.</strong> Les projets et dossiers sont enregistrés sur le serveur pour chaque utilisateur HA. Les projets locaux peuvent être migrés au premier démarrage depuis le navigateur d’origine. JavaScript et TypeScript disposent de la coloration syntaxique, de numéros de ligne et de barres d’outils dédiées. Les icônes et couleurs correspondent entre le sélecteur, l’arborescence et les filtres. Blocks A et Blocks JS ont des filtres distincts. La largeur automatique du volet reste réglable par la poignée.</li><li><strong>Blocks A et Blocks JS.</strong> Les deux utilisent le catalogue intégré de Blocks for HA. Blocks A exporte des automatisations HA en YAML. Blocks JS génère le JavaScript pour la simulation et le moteur. Les blocs ioBroker inconnus sont conservés sous forme de blocs de remplacement et bloquent la génération du code jusqu’à leur remplacement. Associer les identifiants d’objets ioBroker aux entités HA correspondantes.</li><li><strong>Diagramme fonctionnel.</strong> La barre supérieure comporte les icônes de simulation, d’avancement d’une seconde et de réinitialisation. Le format de sortie et l’aperçu sont à droite. Les connexions peuvent être déplacées vers une autre entrée et les valeurs des signaux s’affichent à l’entrée cible.</li><li><strong>Moteur serveur.</strong> Le bouton de lecture lance JavaScript, TypeScript transpilé ou Blocks JS sur le serveur HA. L’arrêt et le redémarrage sont disponibles dans l’éditeur. L’état et le journal restent accessibles depuis un autre navigateur. Le <strong>test</strong> séparé utilise des états et événements simulés. Les scripts et automatisations YAML sont exécutés par Home Assistant après import.</li></ul><h3 id="configurer-le-moteur-en-direct" tabindex="-1">Configurer le moteur en direct <a class="header-anchor" href="#configurer-le-moteur-en-direct" aria-label="Permalink to &quot;Configurer le moteur en direct&quot;">​</a></h3><p>Dans <strong>Paramètres → Applications → HA Logic Studio Pro → Configuration</strong>, ajouter les entrées nécessaires, enregistrer puis redémarrer l’application. Les listes sont vides par défaut. Exemple avec une entrée booléenne dédiée au test :</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_read_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_write_entities</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">input_boolean.logic_studio_runtime_test</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">runtime_events</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">logic_studio_runtime_test</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>L’autorisation d’écriture inclut la lecture. <code>ha.readState</code> et <code>ha.readAttribute</code> renvoient les dernières valeurs confirmées par HA. <code>ha.onState</code>, <code>ha.onAttribute</code> et <code>ha.onEvent</code> réagissent aux changements et événements autorisés. <code>ha.callAction</code> permet la commutation, la modification des entrées numériques, textuelles ou de sélection et l’appui sur des boutons pour une cible autorisée. <code>ha.schedule</code> accepte des motifs horaires et des heures fixes, avec des jours de la semaine facultatifs, dans le fuseau horaire de HA.</p><p>Après le redémarrage de l’application, les scripts doivent être relancés. En cas de perte de connexion ou de refus d’une action, le moteur arrête le script et journalise l’erreur. Les déclencheurs astronomiques et la reconnexion automatique restent à ajouter.</p><p><strong>Vérifié sur .193 avec HA 2026.11.1.</strong> Le moteur a lu l’état et un attribut de l’entrée de test, l’a activée par un horaire et l’a désactivée à la réception d’un événement HA réel. Les deux changements d’état ont été signalés. Un horaire Blocks JS importé s’est exécuté toutes les deux secondes. Les tests précédents ont vérifié le démarrage, l’arrêt, le redémarrage et la poursuite de l’exécution après avoir quitté Studio, avec JavaScript et TypeScript.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/ha-logic-studio-pro-v0.1.23" target="_blank" rel="noreferrer">Mise à jour de test GitHub et ZIP</a> · <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/tree/master/ha_logic_studio_pro" target="_blank" rel="noreferrer">Application dans le dépôt commun</a></p><h2 id="installation-de-test-depuis-github" tabindex="-1">Installation de test depuis GitHub <a class="header-anchor" href="#installation-de-test-depuis-github" aria-label="Permalink to &quot;Installation de test depuis GitHub&quot;">​</a></h2><p><a href="https://my.home-assistant.io/redirect/supervisor_add_addon_repository/?repository_url=https%3A%2F%2Fgithub.com%2Frockbaer2007%2Fugso-ha-mqtt-addons" target="_blank" rel="noreferrer"><img src="https://my.home-assistant.io/badges/supervisor_add_addon_repository.svg" alt="Ajouter le dépôt à Home Assistant"></a></p><ol><li>Dans <strong>Paramètres → Applications → Boutique d’applications → Dépôts</strong>, ajouter l’adresse ci-dessous. Si « UGSo HA Apps » est déjà configuré, rechercher les mises à jour.</li><li>Sélectionner et installer <strong>UGSo Logic Studio</strong>. Activer le mode avancé du profil HA si les applications expérimentales sont masquées.</li><li>Démarrer puis ouvrir l’interface. Compatible <strong>HA OS/Supervised</strong>, <strong>amd64 et aarch64</strong>. La première construction du conteneur peut prendre plusieurs minutes. Ce n’est pas un paquet frontend HACS/Marketplace.</li></ol><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://github.com/rockbaer2007/ugso-ha-mqtt-addons</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><strong>Conserver une installation locale existante :</strong> les applications GitHub et locale ont des identifiants de dépôt et des données séparés. Exporter l’ancien plan en JSON avec <strong>Projekt</strong>, puis utiliser <strong>Öffnen</strong> dans l’application GitHub. Aucune migration ou désinstallation automatique. Chaque application conserve projet et réglages de palette sous <code>/data</code>.</p><p><strong>Mettre à jour une application GitHub existante :</strong> sauvegarder d’abord, rechercher les mises à jour dans le gestionnaire d’applications puis choisir <strong>UGSo Logic Studio → Mettre à jour</strong>. Conserver l’installation : <code>/data</code>, les identifiants d’entités et les plans existants sont préservés. Ne pas désinstaller ni changer d’identifiant d’application. Sur .193, le plan original, les favoris, les blocs récents et les catégories repliées ont été conservés après la mise à jour.</p><h2 id="langue-barre-d-outils-et-documentation" tabindex="-1">Langue, barre d’outils et documentation <a class="header-anchor" href="#langue-barre-d-outils-et-documentation" aria-label="Permalink to &quot;Langue, barre d’outils et documentation&quot;">​</a></h2><p>Choisir <strong>Langue → Deutsch / English / Français</strong> dans l’en-tête. Menus, descriptions des blocs, sélecteur d’entités et dialogues d’import/export changent sans rechargement. Le choix est enregistré avec les préférences du navigateur/de l’application. <strong>Noms personnels, identifiants d’entités, valeurs, noms des bornes et code YAML/JavaScript généré ne sont pas traduits.</strong></p><p><strong>Documentation</strong>, à droite, présente les raccourcis implémentés et, pour le bloc sélectionné, sa description et ses entrées/sorties. <strong>Ctrl+Z / Ctrl+Y</strong> : annuler/rétablir ; <strong>Suppr</strong> : supprimer la sélection ; <strong>Échap</strong> : annuler une connexion/fermer un menu. Tab et Entrée/Espace permettent de choisir et connecter les bornes. Les commandes du débogueur de l’éditeur de référence ioBroker ne sont pas présentées comme disponibles.</p><p>La barre regroupe <strong>Annuler/rétablir → Projet → Simulation → Sortie</strong>. Les trois boutons de simulation ont les mêmes dimensions et des bordures distinctes. Le menu Projet propose aussi <strong>Nouveau projet</strong> et <strong>Charger l’exemple</strong>. Le sélecteur d’entités s’ouvre via l’icône <strong>à côté de l’identifiant d’entité HA</strong> dans les propriétés STATE_IN/STATE_OUT ; l’ancien bouton supérieur est retiré.</p><p><img src="`+t+'" alt="Documentation allemande sur .193 avec le plan original conservé"></p><p><img src="'+r+'" alt="Documentation anglaise du même plan sur .193"></p><p><img src="'+n+'" alt="Documentation française du même plan sur .193"></p><h2 id="deux-types-de-plans" tabindex="-1">Deux types de plans <a class="header-anchor" href="#deux-types-de-plans" aria-label="Permalink to &quot;Deux types de plans&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Plan</th><th>Usage et sortie</th></tr></thead><tbody><tr><td>Flux de valeurs</td><td>Entrées/sorties typées, logique, calcul, sélection, mémoires, fronts, temporisateurs et compteurs. 33 types implémentés ; les autres références sont marquées comme modèles. Export YAML d’automatisation HA, YAML de script HA ou fonction JavaScript avec interface hôte.</td></tr><tr><td>Flux HA natif</td><td>Importer automatisations, scripts et blueprints en blocs imbriqués. 53 types HA supplémentaires : déclencheurs, conditions, branches, boucles, attentes, variables et entrées de blueprint. Export uniquement en YAML HA natif.</td></tr></tbody></table><p>La simulation des flux de valeurs utilise des valeurs de démonstration/instantanées. Les blocs persistants nécessitent les helpers texte HA documentés ou un hôte mémoire JavaScript. Les flux HA natifs ne sont ni exécutés dans l’éditeur ni traduits automatiquement en JavaScript. La sortie JavaScript n’est pas un script ioBroker.</p><h2 id="connexions-a-la-souris-et-mini-vue" tabindex="-1">Connexions à la souris et mini-vue <a class="header-anchor" href="#connexions-a-la-souris-et-mini-vue" aria-label="Permalink to &quot;Connexions à la souris et mini-vue&quot;">​</a></h2><p>Maintenir le bouton de la souris sur une borne colorée, faire glisser vers une borne opposée compatible puis relâcher. Le curseur devient une croix et un aperçu du lien suit la souris. Les cibles compatibles sont marquées en vert ; les entrées incompatibles ou occupées en rouge. Le glissement d’une entrée vers une sortie fonctionne aussi. <strong>Échap</strong> ou relâcher sur une zone vide annule ; <strong>Annuler</strong> retire un lien nouvellement créé.</p><p><strong>BOOL se connecte uniquement à BOOL.</strong> Les types identiques sont compatibles ; la conversion élargissante <code>INT → REAL</code> est aussi autorisée. Les bornes explicitement <code>ANY</code> sont universelles. Nombres et textes ne sont pas convertis implicitement en BOOL. Une entrée accepte un seul lien ; types incompatibles, bornes de même direction, liens vers le même bloc et cycles sont refusés avec une explication. Au clavier, sélectionner la sortie avec Tab/Entrée, puis l’entrée et Entrée.</p><p><img src="'+i+'" alt="Bornes BOOL compatibles reliées à la souris sur .193"></p><p><img src="'+o+'" alt="Connexion STRING vers BOOL refusée avec une erreur de type explicite"></p><p>En bas à droite, la <strong>MiniMap</strong> affiche les positions colorées des blocs et la zone visible. Faire glisser dans la MiniMap pour naviguer et utiliser la molette pour zoomer. Faire glisser le canevas vide déplace la vue ; <strong>+/−</strong> règlent le zoom et <strong>Alles anzeigen</strong> cadre tous les blocs. Déplacer un bloc par son en-tête. L’attribution <strong>React Flow</strong> reste visible en bas à droite. Depuis 0.1.8, la bibliothèque fonctionne réellement dans l’éditeur ; la logique métier, la validation des types et les exportateurs restent propres à Logic Studio.</p><p><img src="'+a+'" alt="Canevas React Flow avec plan original conservé et MiniMap sur .193"></p><p><img src="'+l+'" alt="Test local React Flow avec blocs typés"></p><p>Les images suivantes documentent aussi les tests précédents de 0.1.7.</p><p><img src="'+u+'" alt="Mini-vue avec positions des blocs et cadre visible sur .193"></p><h2 id="importation-et-modification" tabindex="-1">Importation et modification <a class="header-anchor" href="#importation-et-modification" aria-label="Permalink to &quot;Importation et modification&quot;">​</a></h2><p>Ouvrir <strong>HA importieren</strong>, choisir automatisations/scripts/blueprints, puis <strong>Aus HA einlesen</strong>, un fichier YAML/JSON ou du texte. Sélectionner une entrée, vérifier l’aperçu et choisir <strong>Import übernehmen</strong>. Sauvegarder d’abord le projet existant en JSON ; des sauvegardes du projet et des sources sont aussi créées.</p><p>Le dossier de configuration HA est monté <strong>en lecture seule</strong>. L’application lit <code>automations.yaml</code>, <code>scripts.yaml</code> et les fichiers blueprint. Avant analyse, les sources sont copiées sous <code>/data/ha-source-backups/&lt;horodatage&gt;/</code> avec leurs noms d’origine. <code>secrets.yaml</code> n’est pas ouvert ; <code>!secret</code> et <code>!include</code> ne sont pas résolus. Importer manuellement les fichiers référencés par les inclusions.</p><p>Les liens orange <strong>FLOW</strong> représentent l’ordre et les branches : sortie de branche → <strong>DO</strong>, puis <strong>NEXT → DO</strong>. Les liens jaunes <strong>VALUE/REF</strong> montrent les paramètres de blueprint et leur utilisation <code>!input</code>. Configuration HA et chemins de branche sont modifiables en JSON. Les clés de paramètres/champs doivent être uniques. Les sections inconnues restent <strong>YAML_ORIGINAL</strong> ; des liens manquants peuvent bloquer l’export.</p><p><img src="'+c+'" alt="Aperçu d’importation des blueprints HA existants"></p><p>Le <strong>menu ⋮</strong> de chaque bloc propose <strong>Eigenschaften</strong> (propriétés), <strong>Duplizieren</strong> (dupliquer) et <strong>Löschen</strong> (supprimer). La duplication copie les propriétés sans liens. La suppression retire les liens associés ; Annuler les restaure. Recherche, favoris et blocs récents facilitent la sélection.</p><p><img src="'+p+'" alt="Menu à trois points d’un bloc"></p><h2 id="validation-et-limites" tabindex="-1">Validation et limites <a class="header-anchor" href="#validation-et-limites" aria-label="Permalink to &quot;Validation et limites&quot;">​</a></h2><p><strong>0.1.12 sur .193 / HA Core 2026.10.4 :</strong> Application locale mise à jour depuis 0.1.8 après sauvegarde complète. DE/EN/FR, documentation et sélection d’entités HA réelles validés. Le français reste mémorisé après rechargement du navigateur, redémarrage de l’application et nouveau chargement du projet enregistré ; l’allemand a ensuite été rétabli. Le JSON ne diffère <strong>que par la version</strong> : cinq blocs, trois liens, noms, valeurs et positions sont identiques. Le YAML généré est identique en EN et FR. Aucun appareil commandé. <strong>31 tests Node et neuf tests Python</strong> réussis. Les anciens rapports ci-dessous sont conservés comme historique.</p><p><img src="'+d+'" alt="Retour à l’allemand après redémarrage réussi sur .193"></p><p><strong>0.1.8 sur .193 / HA Core 2026.10.4 :</strong> Application locale existante mise à jour après sauvegarde complète. Connexions BOOL à la souris, refus STRING→BOOL, entrées occupées, déplacement/annulation, duplication, zoom et MiniMap validés. Le sélecteur lit les entités HA ; un script imbriqué avec If/Then/Else, Delay et Stop a été importé puis exporté sans modification de structure. Le plan original a été restauré et comparé après rechargement : <strong>identifiants, positions, paramètres et trois liens inchangés</strong>, ainsi que favoris, blocs récents et catégories repliées. Aucun appareil commandé. Construction Docker et test HTTP du conteneur réussis, ainsi que <strong>29 tests Node et huit tests Python</strong>. Images de l’interface allemande. Le changement clair/sombre n’a pas été retesté manuellement à cette étape.</p><p>La base fonctionnelle <strong>0.1.5</strong> a été testée sur <strong>.193 / HA Core 2026.10.4</strong> : import d’un blueprint réel, exemples d’automatisation/script/blueprint, exports YAML identiques sur le fond et actions du menu. <strong>0.1.6</strong> est sa première distribution publique. 22 tests Node et huit tests Python vérifient export, persistance, branches et import sûr ; les contrôles GitHub construisent aussi le conteneur.</p><p><strong>0.1.7 sur .193 / HA Core 2026.10.4 :</strong> tests réels à la souris réussis pour BOOL → BOOL et le sens inverse. STRING → BOOL et une entrée occupée ont été refusés. Mini-vue, navigation par clic et touche Début vérifiées. Le plan original a été rétabli et comparé à sa sauvegarde : <strong>cinq blocs, trois liens et tous les réglages de palette conservés</strong>, y compris après la mise à jour locale vers 0.1.7. Sauvegardes HA complète et projet/réglages séparées créées au préalable ; aucun appareil commandé. <strong>26 tests Node et huit tests Python</strong> réussissent actuellement. Les captures montrent l’interface allemande.</p><p>L’éditeur ne valide pas toute la sémantique HA : vérifier cibles, templates et sélecteurs dans HA. Commentaires, ancres YAML et mise en forme ne sont pas reconstruits. Limites : <strong>1 Mo, 200 blocs, 500 liens</strong>, imbrication limitée et jusqu’à 250 fichiers blueprint dans les dossiers habituels. Régulateurs, calendrier et sous-plans personnalisés restent partiellement des modèles.</p><p>Pour un test local, extraire tout le ZIP, installer Python 3.10+ et les dépendances <code>requirements.txt</code>, puis lancer <strong>Start-Demo.cmd</strong> sous Windows. <code>http://127.0.0.1:4180/</code> affiche des entités de démonstration sans connexion HA. Le ZIP contient aussi <code>addon/logic_studio/</code> pour une installation locale.</p><p><a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/issues" target="_blank" rel="noreferrer">Signaler les problèmes sur GitHub</a> avec versions, architecture et petit exemple anonymisé. Ne pas publier identifiants, automatisations personnelles ou sauvegardes complètes. Guides et rapport de test sont inclus. Licence MIT ; attribution des métadonnées de blocs dans <code>THIRD-PARTY.txt</code>.</p>',57)])])}const E=m(v,[["render",f]]);export{y as __pageData,E as default};
